  1→import { Injectable, ConflictException, NotFoundException } from '@nestjs/common';
  2→import { InjectRepository } from '@nestjs/typeorm';
  3→import { ConfigService } from '@nestjs/config';
  4→import { Repository } from 'typeorm';
  5→import { Vault } from './entities/vault.entity';
  6→import { PinnedCid } from './entities/pinned-cid.entity';
  7→import { FolderIpns } from '../ipns/entities/folder-ipns.entity';
  8→import { User } from '../auth/entities/user.entity';
  9→import { InitVaultDto, VaultResponseDto } from './dto/init-vault.dto';
 10→import { VaultExportDto } from './dto/vault-export.dto';
 11→import { QuotaResponseDto } from './dto/quota.dto';
 12→import { VaultConfigResponseDto } from './dto/vault-config.dto';
 13→import { TeeKeyStateService } from '../tee/tee-key-state.service';
 14→import { TeeKeysDto } from '../tee/dto/tee-keys.dto';
 15→
 16→/**
 17→ * Storage quota limit: 500 MiB
 18→ */
 19→export const QUOTA_LIMIT_BYTES = 500 * 1024 * 1024; // 524,288,000 bytes
 20→
 21→@Injectable()
 22→export class VaultService {
 23→  constructor(
 24→    @InjectRepository(Vault)
 25→    private readonly vaultRepository: Repository<Vault>,
 26→    @InjectRepository(PinnedCid)
 27→    private readonly pinnedCidRepository: Repository<PinnedCid>,
 28→    @InjectRepository(FolderIpns)
 29→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 30→    @InjectRepository(User)
 31→    private readonly userRepository: Repository<User>,
 32→    private readonly teeKeyStateService: TeeKeyStateService,
 33→    private readonly configService: ConfigService
 34→  ) {}
 35→
 36→  /**
 37→   * Get application configuration including recycle bin retention period.
 38→   */
 39→  getConfig(): VaultConfigResponseDto {
 40→    const raw = this.configService.get<string>('RECYCLE_BIN_RETENTION_DAYS');
 41→    let retentionDays = Number(raw);
 42→    if (!Number.isFinite(retentionDays) || retentionDays < 0) {
 43→      retentionDays = 30;
 44→    }
 45→    return {
 46→      recycleBinRetentionDays: retentionDays,
 47→    };
 48→  }
 49→
 50→  /**
 51→   * Initialize a new vault for a user
 52→   * Creates the vault with encrypted keys on first sign-in
 53→   *
 54→   * @throws ConflictException if vault already exists for user
 55→   */
 56→  async initializeVault(userId: string, dto: InitVaultDto): Promise<VaultResponseDto> {
 57→    // Check if vault already exists
 58→    const existingVault = await this.vaultRepository.findOne({
 59→      where: { ownerId: userId },
 60→    });
 61→
 62→    if (existingVault) {
 63→      throw new ConflictException('Vault already exists for this user');
 64→    }
 65→
 66→    // Decode hex strings to buffers
 67→    const vault = this.vaultRepository.create({
 68→      ownerId: userId,
 69→      ownerPublicKey: Buffer.from(dto.ownerPublicKey, 'hex'),
 70→      rootIpnsName: dto.rootIpnsName,
 71→      initializedAt: null,
 72→    });
 73→
 74→    const savedVault = await this.vaultRepository.save(vault);
 75→
 76→    // Ensure root folder IPNS entry exists for publish tracking.
 77→    // The IPNS publish endpoint may have already created this row (clients
 78→    // publish the root folder IPNS record before calling /vault/init).
 79→    // Try insert first; on duplicate key, update isRoot instead.
 80→    try {
 81→      const rootFolderIpns = this.folderIpnsRepository.create({
 82→        userId,
 83→        ipnsName: dto.rootIpnsName,
 84→        latestCid: null,
 85→        sequenceNumber: '0',
 86→        encryptedIpnsPrivateKey: null,
 87→        keyEpoch: null,
 88→        isRoot: true,
 89→      });
 90→      await this.folderIpnsRepository.save(rootFolderIpns);
 91→    } catch (error) {
 92→      // Row already exists (from IPNS publish endpoint) — mark as root
 93→      if ((error as { code?: string }).code === '23505') {
 94→        await this.folderIpnsRepository.update(
 95→          { userId, ipnsName: dto.rootIpnsName },
 96→          { isRoot: true }
 97→        );
 98→      } else {
 99→        throw error;
100→      }
101→    }
102→
103→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
104→    return this.toVaultResponse(savedVault, teeKeys);
105→  }
106→
107→  /**
108→   * Get vault for a user
109→   *
110→   * @throws NotFoundException if vault does not exist
111→   */
112→  async getVault(userId: string): Promise<VaultResponseDto> {
113→    const vault = await this.vaultRepository.findOne({
114→      where: { ownerId: userId },
115→    });
116→
117→    if (!vault) {
118→      throw new NotFoundException('Vault not found');
119→    }
120→
121→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
122→    return this.toVaultResponse(vault, teeKeys);
123→  }
124→
125→  /**
126→   * Check if vault exists for user (returns null if not)
127→   */
128→  async findVault(userId: string): Promise<VaultResponseDto | null> {
129→    const vault = await this.vaultRepository.findOne({
130→      where: { ownerId: userId },
131→    });
132→
133→    if (!vault) return null;
134→
135→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
136→    return this.toVaultResponse(vault, teeKeys);
137→  }
138→
139→  /**
140→   * Get current storage quota usage for a user
141→   */
142→  async getQuota(userId: string): Promise<QuotaResponseDto> {
143→    const result = await this.pinnedCidRepository
144→      .createQueryBuilder('pin')
145→      .select('COALESCE(SUM(pin.size_bytes), 0)', 'total')
146→      .where('pin.user_id = :userId', { userId })
147→      .getRawOne<{ total: string }>();
148→
149→    const usedBytes = parseInt(result?.total ?? '0', 10);
150→    const remainingBytes = Math.max(0, QUOTA_LIMIT_BYTES - usedBytes);
151→
152→    return {
153→      usedBytes,
154→      limitBytes: QUOTA_LIMIT_BYTES,
155→      remainingBytes,
156→    };
157→  }
158→
159→  /**
160→   * Check if user has sufficient quota for additional storage
161→   *
162→   * @returns true if (current usage + additionalBytes) <= quota limit
163→   */
164→  async checkQuota(userId: string, additionalBytes: number): Promise<boolean> {
165→    const quota = await this.getQuota(userId);
166→    return quota.usedBytes + additionalBytes <= QUOTA_LIMIT_BYTES;
167→  }
168→
169→  /**
170→   * Record a pinned CID for quota tracking
171→   * Uses upsert (ON CONFLICT DO NOTHING) for idempotency
172→   */
173→  async recordPin(userId: string, cid: string, sizeBytes: number): Promise<void> {
174→    await this.pinnedCidRepository
175→      .createQueryBuilder()
176→      .insert()
177→      .into(PinnedCid)
178→      .values({
179→        userId,
180→        cid,
181→        sizeBytes: sizeBytes.toString(),
182→      })
183→      .orIgnore() // ON CONFLICT DO NOTHING for idempotency
184→      .execute();
185→  }
186→
187→  /**
188→   * Remove a pinned CID record
189→   * Idempotent - no error if CID not found
190→   */
191→  async recordUnpin(userId: string, cid: string): Promise<void> {
192→    await this.pinnedCidRepository.delete({
193→      userId,
194→      cid,
195→    });
196→  }
197→
198→  /**
199→   * Mark vault as initialized (first file uploaded)
200→   */
201→  async markInitialized(userId: string): Promise<void> {
202→    await this.vaultRepository.update({ ownerId: userId }, { initializedAt: new Date() });
203→  }
204→
205→  /**
206→   * Get export data for independent recovery.
207→   * Returns the minimal set of fields needed to reconstruct the vault:
208→   * root IPNS name + encrypted root keys + derivation hints.
209→   */
210→  async getExportData(userId: string): Promise<VaultExportDto> {
211→    const vault = await this.vaultRepository.findOne({
212→      where: { ownerId: userId },
213→    });
214→
215→    if (!vault) {
216→      throw new NotFoundException('Vault not found');
217→    }
218→
219→    const user = await this.userRepository.findOne({
220→      where: { id: userId },
221→    });
222→
223→    return {
224→      format: 'cipherbox-vault-export',
225→      version: '1.0',
226→      exportedAt: new Date().toISOString(),
227→      rootIpnsName: vault.rootIpnsName,
228→      derivationMethod: user ? 'web3auth' : null,
229→    };
230→  }
231→
232→  /**
233→   * Convert Vault entity to response DTO with hex-encoded fields
234→   */
235→  private toVaultResponse(vault: Vault, teeKeys: TeeKeysDto | null = null): VaultResponseDto {
236→    return {
237→      id: vault.id,
238→      ownerPublicKey: vault.ownerPublicKey.toString('hex'),
239→      rootIpnsName: vault.rootIpnsName,
240→      createdAt: vault.createdAt,
241→      initializedAt: vault.initializedAt,
242→      teeKeys,
243→    };
244→  }
245→}
246→

import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
  ManyToOne,
  JoinColumn,
  Index,
} from 'typeorm';
import { User } from '../../auth/entities/user.entity';

@Entity('vaults')
export class Vault {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Index({ unique: true })
  @Column({ type: 'uuid', name: 'owner_id' })
  ownerId!: string;

  @ManyToOne(() => User, { onDelete: 'CASCADE' })
  @JoinColumn({ name: 'owner_id' })
  owner!: User;

  /**
   * User's secp256k1 public key (uncompressed, 65 bytes)
   * Used for ECIES encryption of vault keys
   */
  @Column({ type: 'bytea', name: 'owner_public_key' })
  ownerPublicKey!: Buffer;

  /**
   * IPNS name (libp2p-key multihash of public key)
   * Used to identify the root folder's IPNS record
   */
  @Column({ type: 'varchar', length: 255, name: 'root_ipns_name' })
  rootIpnsName!: string;

  @CreateDateColumn({ name: 'created_at' })
  createdAt!: Date;

  /**
   * Set when vault is first used (first file uploaded)
   * Null until vault contains actual content
   */
  @Column({ type: 'timestamp', nullable: true, name: 'initialized_at' })
  initializedAt!: Date | null;

  @UpdateDateColumn({ name: 'updated_at' })
  updatedAt!: Date;
}

